const fs=require('fs');function edit(p,f){fs.writeFileSync(p,f(fs.readFileSync(p,'utf8')))}
edit('src/flip.ts',s=>s.replace('const W=220,H=320;','export const colonIsLit=(timestamp=Date.now())=>timestamp%1000<500;\nconst W=220,H=320;').replace('width:number,height:number){','width:number,height:number,colonLit=true){').replace('for(const cy of [151,257]){const glow=',"c.save();c.globalAlpha=colonLit?1:.06;\n  for(const cy of [151,257]){const glow=").replace('c.restore();return a;','c.restore();c.restore();return a;'));
edit('src/plugin/actions/flip.ts',s=>s.replace('FlipRenderer,FlipState,clockDigits,loadFlipFont','FlipRenderer,FlipState,clockDigits,loadFlipFont,colonIsLit').replace("const p=st.clock.progress(now,s),key=JSON.stringify(s)+st.clock.revision+':'+p;","const lit=colonIsLit();const p=st.clock.progress(now,s),key=JSON.stringify(s)+st.clock.revision+':'+p+':'+lit;").replace('size(s.ActionGeometry?.height,410));','size(s.ActionGeometry?.height,410),lit);'));
edit('flip-preview.html',s=>s.replace('FlipRenderer,FlipState,clockDigits,loadFlipFont','FlipRenderer,FlipState,clockDigits,loadFlipFont,colonIsLit').replace("const p=state.progress(now,s),key=state.revision+':'+p;","const lit=colonIsLit();const p=state.progress(now,s),key=state.revision+':'+p+':'+lit;").replace('p,1080,410);','p,1080,410,lit);'));